def copy_traceback():
    # JavaScript function to copy traceback to clipboard
    var tracebackArea = document.getElementById('traceback_area');
    var range = document.createRange();
    range.selectNode(tracebackArea);
    window.getSelection().removeAllRanges();
    window.getSelection().addRange(range);
    document.execCommand('copy');
    window.getSelection().removeAllRanges();

